test('15F S000045 UI splits six berries into three plus three and produces five plus five',async({page},testInfo)=>{await boot(page,{player1:{hand:['S000045'],supplies:Array(6).fill('R000003')}});await page.evaluate(()=>{player1.resourceState.classical={...createEmptyClassicalResources(),aria:100,lenya:100,nourriture:100,bois:100};for(const s of player1.supplies){s.currentProduction={...s.currentProduction,aria:100,lenya:100,bois:100};s.productionState.currentVector={...s.currentProduction};}recomputeClassicalResources(player1)});await play(page,'S000045');const piles=await page.evaluate(()=>[...qs(playerZoneSelector(player1,'appro')).querySelectorAll('.fc[data-botanical-card="R000003"]')].map(e=>({count:Number(e.dataset.botanicalCount),production:Number(e.dataset.res)})));await testInfo.attach('six-berry-piles',{body:Buffer.from(JSON.stringify(piles)),contentType:'application/json'});expect(piles.map(s=>s.count)).toEqual([3,3]);expect(piles.map(s=>s.production)).toEqual([5,5]);expect((await snapshot(page)).resources.nourriture).toBe(10);expect(await page.evaluate(()=>player1.supplies.filter(s=>s.cardId==='R000003').length)).toBe(6)});
