async function both(page){return page.evaluate(()=>[player1,player2].map(p=>({key:p.key,characterId:p.characterId,hand:[...p.hand],deck:playerDrawPile(p).map(getRuntimeCardId),graveyard:p.graveyard.map(getRuntimeCardId),souls:p.resourceState.souls,resources:{...p.resourceState.classical},hp:batch09AvatarHp(p),supplies:p.supplies.map(i=>({id:i.cardId,instance:i.instanceId})),board:livingServantCardsForPlayer(p).map(fc=>({id:fc.dataset.id,atk:Number(fc.dataset.atk),hp:Number(fc.dataset.pdv),max:Number(fc.dataset.pdvMax)}))})))}
async function attack(page,attackerId,targetId){return page.evaluate(async({attackerId,targetId})=>{const a=findBoardCard(player1,attackerId),t=findBoardCard(player2,targetId);tryAttack(a);if(attackingFC!==a)return false;await resolveCombat(a,t);return true},{attackerId,targetId})}
async function ownerRound(page){await page.evaluate(async()=>{await endTurn();await endTurn()})}
async function supplyStacks(page){return page.evaluate(()=>[...qs(playerZoneSelector(player1,'appro')).querySelectorAll('.fc[data-botanical-card]')].map(fc=>({id:fc.dataset.id,count:Number(fc.dataset.botanicalCount),res:Number(fc.dataset.res),stackId:fc.dataset.botanicalStack,instance:fc.dataset.supplyInstance})))}

