 const result=await page.evaluate(()=>{const t=findBoardCard(player2,'H000001'),a=findBoardCard(player1,'EDG000001');clearBatch05NegativeStatuses(t);tryApplyGel({sourcePlayer:player1,targetFC:t,sourceCardId:'EDG000001',turns:2,type:'cdg'});const own=Number(t.dataset.frozen_cdg);tryApplyGel({sourcePlayer:player2,targetFC:a,sourceCardId:'EDG000001',turns:2,type:'gel'});return {own,opponent:Number(a.dataset.frozen||0),bonus:player1.batch05SnowfallBonus,ownText:batch15fColdCardData('EDG000001',CARDS_DATA.EDG000001,player1).cap,enemyText:batch15fColdCardData('EDG000001',CARDS_DATA.EDG000001,player2).cap}});
 expect(result.own).toBe(3);expect(result.opponent).toBe(0); // Sang-froid on the ice elf is still respected.
