async function stableAvatarHover(page){
 const frames=await page.locator('.batch15f-avatar-selection').evaluate(async panel=>{
  let timer;const frame=()=>new Promise(requestAnimationFrame);
  const observe=async()=>{await frame();for(const animation of [...panel.querySelectorAll('.sort-choice-item')].flatMap(item=>item.getAnimations()).filter(a=>a instanceof CSSTransition&&a.transitionProperty==='transform'&&a.playState!=='finished'))await animation.finished;const samples=[];for(let i=0;i<3;i++){await frame();samples.push([...panel.querySelectorAll('.batch15f-avatar-option')].flatMap(card=>{const r=card.getBoundingClientRect();return [r.x,r.y,r.width,r.height]}))}return samples;};
  try{return await Promise.race([observe(),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Avatar hover transition timeout')),2000)})])}finally{clearTimeout(timer)}
 });for(const sample of frames.slice(1))sample.forEach((v,i)=>expect(Math.abs(v-frames[0][i])).toBeLessThanOrEqual(.5));
}

