// 15F2: real player regressions, recorded before production changes.
async function observe15f2(page){await page.evaluate(()=>{window.__f2visual=[];window.__f2appear=[];const nativeAnimate=Element.prototype.animate;Element.prototype.animate=function(...args){const animation=nativeAnimate.apply(this,args);if(this.matches('.av-portrait,.deck-stack')){const zone=this.matches('.av-portrait')?'avatar':'deck';const detail={zone,src:this.querySelector('img')?.getAttribute('src'),frames:animation.effect.getKeyframes(),at:performance.now()};__f2appear.push({...detail,phase:'start'});animation.finished.then(()=>__f2appear.push({...detail,phase:'end',at:performance.now()}));}return animation;};const seen=new Set(),identities=new WeakMap();let seq=0;const tick=()=>{for(const el of document.querySelectorAll('.batch14d-hand-flight,.batch09-cadaver-flight,.batch15f2-arrival,.batch03-ability-pulse')){if(!identities.has(el))identities.set(el,++seq);const cs=getComputedStyle(el),r=el.getBoundingClientRect(),key=identities.get(el)+'|'+(el.dataset.ownerId||el.dataset.player||'')+'|'+(el.dataset.cardId||el.dataset.id||'')+'|'+el.className+'|'+(el.dataset.flightReason||'');if(seen.has(key))continue;seen.add(key);const p=playerState(el.dataset.ownerId||el.dataset.player),deck=p&&qs(playerZoneSelector(p,'deckBack'))?.getBoundingClientRect();window.__f2visual.push({key,at:performance.now(),handIds:p?[...p.hand]:[],animations:el.getAnimations().map(a=>({name:a.animationName||'',iterations:a.effect.getTiming().iterations,state:a.playState})),classes:el.className,owner:el.dataset.ownerId||el.dataset.player,id:el.dataset.cardId||el.dataset.id,reason:el.dataset.flightReason,image:cs.backgroundImage,shadow:cs.boxShadow,border:cs.borderColor,animation:cs.animationName,fromX:el.style.getPropertyValue('--from-x'),fromY:el.style.getPropertyValue('--from-y'),deck:deck?{x:deck.x,y:deck.y,width:deck.width,height:deck.height}:null,rect:{x:r.x,y:r.y,width:r.width,height:r.height}});}requestAnimationFrame(tick);};requestAnimationFrame(tick);});}
async function visual15f2(page,testInfo){const values=await page.evaluate(()=>window.__f2visual||[]);await testInfo.attach('observed-real-visual-phases',{body:Buffer.from(JSON.stringify(values,null,2)),contentType:'application/json'});return values;}
