// 15F3 regressions observe actual DOM animation objects through the full notification.
async function observe15f3Hand(page){
 await page.waitForFunction(()=>[...qs(playerZoneSelector(player1,'hand')).querySelectorAll('.hc')].every(c=>c.style.transform && !c.getAnimations().some(a=>a.playState==='running')));
 await page.evaluate(async()=>{await new Promise(requestAnimationFrame);await Promise.all([...qs(playerZoneSelector(player1,'hand')).getAnimations({subtree:true})].filter(a=>a.effect.getTiming().iterations!==Infinity).map(a=>a.finished.catch(()=>{})));window.__f3={motions:[],messages:[],arrivals:[],maxFlights:0};const nativeAnimate=Element.prototype.animate;Element.prototype.animate=function(...args){const animation=nativeAnimate.apply(this,args);if(this.classList.contains('batch15f2-arrival')){const entry={start:performance.now(),reason:this.dataset.flightReason,frames:animation.effect.getKeyframes(),end:null};__f3.arrivals.push(entry);animation.finished.then(()=>entry.end=performance.now());}return animation;};const seen=new WeakSet();let lastMessage='';const sample=()=>{const hand=qs(playerZoneSelector(player1,'hand')),now=performance.now(),notif=qs('#notif');__f3.maxFlights=Math.max(__f3.maxFlights,document.querySelectorAll('.batch14d-hand-flight').length);const message=notif.classList.contains('show')?notif.textContent:'';if(message!==lastMessage){__f3.messages.push({at:now,text:message});lastMessage=message;}for(const node of hand.querySelectorAll('.hc')){for(const a of node.getAnimations()){if(seen.has(a)||!(a instanceof CSSTransition)||a.transitionProperty!=='transform')continue;seen.add(a);const entry={at:now,token:hand.dataset.renderToken,id:node.dataset.id,occurrence:node.dataset.handOccurrence,frames:a.effect.getKeyframes(),duringMessage:!!message,end:null};__f3.motions.push(entry);a.finished.then(()=>entry.end=performance.now(),()=>entry.cancel=performance.now());}}requestAnimationFrame(sample)};requestAnimationFrame(sample)});
}
async function finish15f3Hand(page,testInfo){
 await page.waitForFunction(()=>!qs('#notif').classList.contains('show')&&!collectionBatch15EState.active&&batch15fDrawTasks.size===0);
 await page.evaluate(()=>{__f3.beforeLayout=[...qs(playerZoneSelector(player1,'hand')).children].map(n=>{const r=n.getBoundingClientRect();return [r.x,r.y,r.width,r.height]})});
 await page.evaluate(async()=>{const ready=new Promise(resolve=>renderPlayerHand(player1,{onLayoutReady:resolve}));await new Promise(requestAnimationFrame);__f3.firstPaintLayout=[...qs(playerZoneSelector(player1,'hand')).children].map(n=>{const r=n.getBoundingClientRect();return [r.x,r.y,r.width,r.height]});await ready;await new Promise(requestAnimationFrame)});
 await page.evaluate(()=>{__f3.afterLayout=[...qs(playerZoneSelector(player1,'hand')).children].map(n=>{const r=n.getBoundingClientRect();return [r.x,r.y,r.width,r.height]})});
 const result=await page.evaluate(()=>__f3);writeFileSync(testInfo.outputPath('hand-timeline.json'),JSON.stringify(result,null,2));await testInfo.attach('real-hand-transitions-and-whole-message',{body:Buffer.from(JSON.stringify(result,null,2)),contentType:'application/json'});expect(result.firstPaintLayout).toHaveLength(result.beforeLayout.length);for(const [i,rect]of result.firstPaintLayout.entries())for(const [k,value]of rect.entries())expect(Math.abs(value-result.beforeLayout[i][k])).toBeLessThanOrEqual(.5);expect(result.afterLayout).toHaveLength(result.beforeLayout.length);for(const [i,rect]of result.afterLayout.entries())for(const [k,value]of rect.entries())expect(Math.abs(value-result.beforeLayout[i][k])).toBeLessThanOrEqual(.5);return result;
}
